SELECT MIN(GSoffered) AS lowest_grade_level
FROM schools
WHERE NCESDist = '0632640' AND GSoffered IS NOT NULL;

SELECT School AS school_name, EILName AS educational_instruction_level_name
FROM schools
WHERE CDSCode = '1612590136051';

SELECT COUNT(DISTINCT language) AS foreign_language_count
FROM foreign_data
WHERE name = 'Swamp';

SELECT MAX(CAST(RNP AS FLOAT)) AS Highest_RNP_Value
FROM Laboratory
WHERE RNP IS NOT NULL;

SELECT MAX(CAST(RNP AS FLOAT)) AS max_anti_RNP_antibody
FROM Laboratory
WHERE CRE < 1.5 AND RNP IS NOT NULL;
